/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 lines=f.read_text().splitlines(); page='?'; hits=set()
 for i,l in enumerate(lines):
  if re.search(r'terminat|cancel',l,re.I):
   hits.update(range(max(0,i-2),min(len(lines),i+5)))
 print('\\nFILE',f.name[:-4])
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if i in hits: print(f'p{page}: {l}')
PY"

